local shape_chunks = {}
for i = 1, 5 do
  shape_chunks[i] = MODULE .. string.format(".shapes_%03d", i)
end

local where -- shape name -> file number, built on the first lookup

-- The registry: a lookup of a shape not loaded yet loads its whole file. An unknown name is nil. A
-- missing file raises, as a missing module does.
local shapes = setmetatable({}, {
  __index = function(registry, name)
    if where == nil then
      where = {}
      for file, shape in string.gmatch(SHAPES, "(%d+) ([^\n]+)") do
        where[shape] = file
      end
      SHAPES = nil
    end
    local file = where[name]
    if file == nil then
      return nil
    end
    for k, node in pairs(require(MODULE .. ".shapes_" .. file)) do
      rawset(registry, k, node)
    end
    return rawget(registry, name)
  end,
})

local classes = {}

classes.AclNotFound = errors.define({
  tag = "AclNotFound",
  categories = {},
  matchers = { { status = 404 } },
  fields = { "code", "message" },
})
classes.DnsRecordAlreadyExists = errors.define({
  tag = "DnsRecordAlreadyExists",
  categories = {},
  matchers = {
    { code = 81057 },
    { code = 81058 },
    { status = 400, message = { includes = "identical record already exists" } },
  },
  fields = { "code", "message" },
})
classes.DnsSettingNotAvailable = errors.define({
  tag = "DnsSettingNotAvailable",
  categories = {},
  matchers = { { code = 1003 } },
  fields = { "code", "message" },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = {},
  matchers = { { status = 403 } },
  fields = { "code", "message" },
})
classes.IncomingZoneTransferNotFound = errors.define({
  tag = "IncomingZoneTransferNotFound",
  categories = {},
  matchers = { { status = 404 } },
  fields = { "code", "message" },
})
classes.InternalDnsNotAvailable = errors.define({
  tag = "InternalDnsNotAvailable",
  categories = {},
  matchers = { { code = 1029 } },
  fields = { "code", "message" },
})
classes.OutgoingZoneTransferNotFound = errors.define({
  tag = "OutgoingZoneTransferNotFound",
  categories = {},
  matchers = { { status = 404 } },
  fields = { "code", "message" },
})
classes.OutgoingZoneTransfersNotAllowed = errors.define({
  tag = "OutgoingZoneTransfersNotAllowed",
  categories = {},
  matchers = { { status = 401 } },
  fields = { "code", "message" },
})
classes.PeerNotFound = errors.define({
  tag = "PeerNotFound",
  categories = {},
  matchers = { { status = 404 } },
  fields = { "code", "message" },
})
classes.RecordNotFound = errors.define({
  tag = "RecordNotFound",
  categories = {},
  matchers = { { code = 81044 } },
  fields = { "code", "message" },
})
classes.TsigNotFound = errors.define({
  tag = "TsigNotFound",
  categories = {},
  matchers = { { status = 404 } },
  fields = { "code", "message" },
})
classes.ViewNotFound = errors.define({
  tag = "ViewNotFound",
  categories = {},
  matchers = { { code = 1015 }, { status = 404 } },
  fields = { "code", "message" },
})

local ops = {}
for i = 1, 1 do
  for name, op in pairs(require(MODULE .. string.format(".ops_%03d", i))) do
    ops[name] = op
  end
end

return {
  name = "cloudflare.dns",
  shapes = shapes,
  errors = classes,
  ops = ops,
  shape_chunks = shape_chunks,
  telemetry = {
    system = "cloudflare-api",
    prefix = "Cloudflare",
    service = "Dns",
    labels = "cloudflare",
    propagate = "w3c",
    response_headers = {
      { header = "x-request-id", name = "http.response.header.x-request-id", transform = "list" },
      { header = "request-id", name = "http.response.header.request-id", transform = "list" },
      { header = "cf-ray", name = "http.response.header.cf-ray", transform = "list" },
    },
  },
}
